 def test_slot2_inverse_exact_and_negative_hunk_matrix(self):
  import hashlib
  from unittest.mock import patch
  source=(ROOT/'certification_admission.py').read_text()
  self.assertEqual(hashlib.sha256(restore_exact_slot2_delta(source).encode()).hexdigest(),SLOT2_BASE_SHA256)
  self.assertEqual(SLOT2_BASE_SHA256,CERTIFICATION_TWO_SOURCE_SHA256)
  self.assertEqual(hashlib.sha256(restore_exact_certification_delta(source).encode()).hexdigest(),CERTIFICATION_TWO_BASE_SHA256)
  with self.assertRaisesRegex(AssertionError,'slot2_source_changed'):restore_exact_slot2_delta(source+'\n# extra byte\n')
  for offset,approved,original in SLOT2_EXACT_HUNKS:
   for label,bad in [('absent',source[:offset]+source[offset+len(approved):]),('different',source[:offset]+'# changed\n'+source[offset+1:]),('moved',approved+source[:offset]+source[offset+len(approved):]),('duplicate',source+approved)]:
    # Bypass only the outer checksum in this negative probe, to prove the inner
    # unique-position/shape check also rejects. Production code is never mocked.
    with self.subTest(offset=offset,mutation=label), patch.dict(globals(),SLOT2_SOURCE_SHA256=hashlib.sha256(bad.encode()).hexdigest()):
     with self.assertRaisesRegex(AssertionError,'slot2_delta_shape_changed'):restore_exact_slot2_delta(bad)
  wrong=list(SLOT2_EXACT_HUNKS);offset,approved,original=wrong[0];wrong[0]=(offset,approved,original+'# wrong baseline\n')
  with patch.dict(globals(),SLOT2_EXACT_HUNKS=wrong):
   with self.assertRaisesRegex(AssertionError,'slot2_baseline_not_exact'):restore_exact_slot2_delta(source)

 def test_slot2_does_not_absorb_business_or_self_skip_mutations(self):
  import hashlib
  expected={'runner.py': '04d68d070b1af8af5d2bfce1e460cfdde0d31d130e16c74725baf764bcf933cd', 'instagram_navigation.py': 'fe3fba2c7b5051a4e5f95adfd98a316ac294de3b87d2b26e6eaa84b0617e2d30', 'follow60_mainline_v2.py': '572a6a9e66c6cf434ef7335675f85e73ab215593eb6e86d99f2677c1c7ba0652'}
  for name,wanted in expected.items():
   source=(ROOT/name).read_bytes()
   def require_exact(value):
    if hashlib.sha256(value).hexdigest()!=wanted:raise AssertionError('business_or_self_skip_changed')
   require_exact(source)
   for bad in (source+b'\n# unrelated\n',source[:-1]):
    with self.subTest(path=name),self.assertRaises(AssertionError):require_exact(bad)
   if name=='runner.py':
    bad=source.replace(b'_verified_current_account_key',b'_wrong_current_account_key',1)
    self.assertNotEqual(bad,source)
    with self.assertRaises(AssertionError):require_exact(bad)

